// main.js (proceso principal). Los remitos son INVENTADOS.
const { app, BrowserWindow, ipcMain } = require('electron');
const path = require('path');

// Este canal responde en el proceso principal, con Node completo.
ipcMain.handle('remitos:contar', (ev, estado) => {
  const datos = [{id:'R-1',estado:'pendiente'},{id:'R-2',estado:'entregado'},{id:'R-3',estado:'pendiente'}];
  return datos.filter(r => r.estado === estado).length;
});

app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: 600, height: 400, show: false,
    webPreferences: { preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true, nodeIntegration: false, sandbox: true } });
  await win.loadFile('index.html');
});

// preload.js: lo único que la página va a poder llamar
const { contextBridge, ipcRenderer } = require('electron');
contextBridge.exposeInMainWorld('remitos', { contar: (estado) => ipcRenderer.invoke('remitos:contar', estado) });

// index.html (proceso de render): script de la página
const pend = window.remitos ? await window.remitos.contar('pendiente') : 'sin puente';
console.log(typeof require, typeof process, pend);
